<script>document.addEventListener('DOMContentLoaded',()=>{const groups=[];const makeGroup=(title,description,anchor,content,keepContainer=false)=>{const details=document.createElement('details'),summary=document.createElement('summary'),body=document.createElement('div');details.className='settings-group';summary.innerHTML=`<span><span class="block text-base font-black text-slate-900">${title}</span><span class="mt-1 block text-sm font-medium text-slate-500">${description}</span></span><span class="settings-chevron text-slate-500">⌄</span>`;body.className='border-t border-slate-100 p-5 sm:p-6';anchor.before(details);details.append(summary,body);if(keepContainer)body.append(content);else{while(content.firstChild)body.append(content.firstChild);content.remove()}groups.push(details);return details};const topCards=[...document.querySelectorAll('section.mx-auto.mb-7.max-w-2xl')],biometricCard=topCards.find(card=>card.querySelector('h2')?.textContent.trim()==='Biometric sign-in'),cameraCard=topCards.find(card=>card.querySelector('h2')?.textContent.trim()==='Camera portal account');if(biometricCard)makeGroup('Biometric sign-in','Enroll the administrator face used with password sign-in.',biometricCard,biometricCard);if(cameraCard)makeGroup('Camera portal account','Manage the restricted guard-house scanner account.',cameraCard,cameraCard);const settingsGrid=document.querySelector('div.grid.gap-7.lg\\:grid-cols-2');if(settingsGrid){const cards=[...settingsGrid.children].filter(node=>node.tagName==='SECTION'),teacherCard=cards.find(card=>card.querySelector('h2')?.textContent.trim()==='Teacher sections');if(teacherCard)teacherCard.remove();const accountGroup=makeGroup('Account security','Change the administrator password or configure password recovery.',settingsGrid,settingsGrid,true);if(teacherCard){const teacherGroup=makeGroup('Teacher sections','Create, rename, and organize grade-level sections.',accountGroup,teacherCard);accountGroup.after(teacherGroup)}}groups.forEach(group=>group.addEventListener('toggle',()=>{if(group.open)groups.forEach(other=>{if(other!==group)other.open=false})}))});</script>
