<script>document.addEventListener('DOMContentLoaded',()=>{const form=document.getElementById('admin-biometric-form'),video=document.getElementById('admin-biometric-video'),frame=document.getElementById('admin-biometric-frame'),button=document.getElementById('admin-enable-camera'),modal=document.getElementById('admin-biometric-camera-modal'),close=document.getElementById('admin-biometric-camera-close'),status=document.getElementById('admin-biometric-camera-status');let stream;const closeCamera=()=>{stream?.getTracks().forEach(track=>track.stop());stream=null;video.srcObject=null;modal.classList.replace('flex','hidden');button.textContent='Enable camera';button.disabled=false};button.onclick=async()=>{modal.classList.replace('hidden','flex');status.textContent='Opening camera…';try{stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'user',width:{ideal:640}},audio:false});video.srcObject=stream;await video.play();status.textContent='Camera ready. Keep your face clearly visible, then enroll.';button.textContent='Camera ready';button.disabled=true}catch(error){status.textContent='Camera access was not granted. Close this window and try again.';button.textContent='Camera access was not granted'}};close.onclick=closeCamera;form.onsubmit=event=>{if(!stream||!video.videoWidth){event.preventDefault();alert('Enable the camera and keep one clear face in view before enrolling.');return}const canvas=document.createElement('canvas');canvas.width=video.videoWidth;canvas.height=video.videoHeight;canvas.getContext('2d').drawImage(video,0,0);frame.value=canvas.toDataURL('image/jpeg',.9)};window.addEventListener('pagehide',()=>stream?.getTracks().forEach(track=>track.stop()))});</script>
