<script>document.addEventListener('DOMContentLoaded',()=>{const form=document.getElementById('attendance-mode-form'),toggle=document.getElementById('half-day-mode-toggle'),title=document.getElementById('attendance-mode-title'),description=document.getElementById('attendance-mode-description'),badge=document.getElementById('attendance-mode-badge'),label=document.getElementById('attendance-mode-control-label'),state=document.getElementById('attendance-mode-state'),status=document.getElementById('attendance-mode-save-status');if(!form||!toggle)return;const render=halfDay=>{const wholeDay=!halfDay;title.textContent=wholeDay?'Whole-day mode':'Half-day mode';title.className='text-xl font-black '+(wholeDay?'text-green-700':'text-amber-700');description.textContent=wholeDay?'Whole day is active: lunch out at 11:40 AM and afternoon time in at 12:20 PM.':'Half day is active: students use the standard time-in/time-out flow.';badge.textContent=wholeDay?'Whole day active':'Half day active';badge.className='rounded-full px-3 py-1 text-sm font-bold '+(wholeDay?'bg-emerald-50 text-emerald-700':'bg-amber-50 text-amber-700');label.textContent=wholeDay?'Switch on half-day mode':'Half-day mode is on';label.className='font-bold '+(wholeDay?'text-green-700':'text-amber-700');state.textContent=wholeDay?'Off · Whole day':'On · Half day';state.className='text-sm font-bold '+(wholeDay?'text-green-700':'text-amber-700')};toggle.addEventListener('change',async()=>{const previous=!toggle.checked;render(toggle.checked);status.textContent='Saving attendance mode…';toggle.disabled=true;try{const data=new FormData(form);const response=await fetch('save-attendance-mode.php',{method:'POST',body:data,credentials:'same-origin',headers:{Accept:'application/json'}});const result=await response.json();if(!response.ok||!result.saved)throw new Error(result.message||'Save failed');status.textContent='Attendance mode saved.'}catch(error){toggle.checked=previous;render(previous);status.textContent='Could not save the mode. Please try again.'}finally{toggle.disabled=false}})});</script>
